'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var abs = require( '@stdlib/math/base/special/abs' );
var floor = require( '@stdlib/math/base/special/floor' );
var max = require( '@stdlib/math/base/special/max' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var native = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var main = require( './../lib/main.js' );
var factory = require( './../lib/factory.js' );
var addon = tryRequire( resolve( __dirname, './../src/addon.node' ) );
var fixtures = require( './fixtures/lapack.json' ).cases;


// VARIABLES //

var opts = {
	'skip': isError( native )
};


// FUNCTIONS //

/**
* Tests exact numeric equality, including signed zero and NaN.
*
* @private
* @param {number} x - first value
* @param {number} y - second value
* @returns {boolean} whether the values agree
*/
function same( x, y ) {
	return ( x === y && ( x !== 0.0 || 1.0/x === 1.0/y ) ) || ( x !== x && y !== y );
}

/**
* Compares all elements of two buffers.
*
* @private
* @param {TypedArray} actual - actual buffer
* @param {TypedArray} expected - expected buffer
* @returns {boolean} whether all elements agree
*/
function sameBuffer( actual, expected ) {
	var i;
	if ( actual.length !== expected.length ) {
		return false;
	}
	for ( i = 0; i < actual.length; i++ ) {
		if ( !same( actual[ i ], expected[ i ] ) ) {
			return false;
		}
	}
	return true;
}

/**
* Returns separate typed inputs for one reference fixture.
*
* @private
* @param {Object} data - fixture
* @returns {Array} typed inputs
*/
function inputs( data ) {
	return [
		new Float64Array( data.DL ),
		new Float64Array( data.D ),
		new Float64Array( data.DU ),
		new Float64Array( ( data.N > 1 ) ? data.N-2 : 0 ),
		new Int32Array( data.N )
	];
}

/**
* Packs values in a guarded typed view with independent indexing.
*
* @private
* @param {Array} values - initial values
* @param {integer} stride - stride length
* @param {boolean} pivot - whether to create pivot indices
* @returns {Object} view and offset
*/
function packed( values, stride, pivot ) {
	var buffer;
	var offset;
	var length;
	var data;
	var i;
	length = 5 + ( values.length*3 );
	buffer = ( pivot ) ? new Int32Array( length+2 ) : new Float64Array( length+2 );
	for ( i = 0; i < buffer.length; i++ ) {
		buffer[ i ] = 97;
	}
	data = buffer.subarray( 1, length+1 );
	offset = ( stride < 0 ) ? 2 + ( (values.length-1)*(-stride) ) : 2;
	for ( i = 0; i < values.length; i++ ) {
		data[ offset+(i*stride) ] = values[ i ];
	}
	return {
		'data': data,
		'offset': offset,
		'buffer': buffer
	};
}


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof native, 'function', 'main export is a function' );
	t.strictEqual( require( './../lib' ), native, 'selects the compiled interface' );
	t.strictEqual( native.length, 6, 'preserves main arity' );
	t.strictEqual( native.ndarray.length, 16, 'preserves ndarray arity' );
	t.end();
});

tape( 'native factors and pivots agree with the independent compiled LAPACK oracle', opts, function test( t ) {
	var expected;
	var actual;
	var values;
	var data;
	var info;
	var i;
	var j;
	var k;
	for ( i = 0; i < fixtures.length; i++ ) {
		data = fixtures[ i ];
		values = inputs( data );
		info = native.apply( null, [ data.N ].concat( values ) );
		t.strictEqual( info, data.expectedInfo, data.name+': status' );
		t.deepEqual( Array.prototype.slice.call( values[ 4 ] ), data.expectedIPIV, data.name+': pivots' );
		expected = [ data.expectedDL, data.expectedD, data.expectedDU, data.expectedDU2 ];
		for ( j = 0; j < 4; j++ ) {
			actual = values[ j ];
			for ( k = 0; k < actual.length; k++ ) {
				t.ok( same( actual[ k ], expected[ j ][ k ] ) || isAlmostSameValue( actual[ k ], expected[ j ][ k ], 4 ), data.name+': factor' );
			}
		}
	}
	t.end();
});

tape( 'native indexed mutation agrees with original JS across independent strides', opts, function test( t ) {
	var expected;
	var strides = [ -2, 0, 3 ];
	var actual;
	var argsJS;
	var viewJS;
	var values;
	var kernel;
	var stride;
	var infoJS;
	var argsC;
	var viewC;
	var calls;
	var infoC;
	var index;
	var code;
	var i;
	var j;
	calls = 0;
	kernel = factory( function instrument() {
		calls += 1;
		return addon.apply( null, arguments );
	} );
	values = [ [ 3, -2, 4, 1 ], [ 1, 5, -1, 4, 2 ], [ 2, -3, 1, 5 ], [ 11, 12, 13 ], [ 17, 18, 19, 20, 21 ] ];
	for ( code = 0; code < 243; code++ ) {
		argsJS = [ 5 ];
		argsC = [ 5 ];
		expected = [];
		actual = [];
		index = code;
		for ( i = 0; i < 5; i++ ) {
			stride = strides[ index%3 ];
			index = floor( index/3 );
			viewJS = packed( values[ i ], stride, i === 4 );
			viewC = packed( values[ i ], stride, i === 4 );
			argsJS.push( viewJS.data, stride, viewJS.offset );
			argsC.push( viewC.data, stride, viewC.offset );
			expected.push( viewJS.buffer );
			actual.push( viewC.buffer );
		}
		infoJS = main.ndarray.apply( null, argsJS );
		infoC = kernel.ndarray.apply( null, argsC );
		t.strictEqual( infoC, infoJS, 'same status for stride combination '+code );
		for ( j = 0; j < 5; j++ ) {
			t.ok( sameBuffer( actual[ j ], expected[ j ] ), 'same complete guarded view '+j+' for combination '+code );
		}
	}
	t.strictEqual( calls, 243, 'all stride combinations execute the real addon' );
	t.end();
});

tape( 'native factorization preserves signed zero and nonfinite operations', opts, function test( t ) {
	var cases = [
		[ [ 0, -0 ], [ -0, 1, 2 ], [ -0, 0 ] ],
		[ [ NaN, 1 ], [ 2, 3, 4 ], [ 1, 1 ] ],
		[ [ 1, NaN ], [ 2, 3, 4 ], [ 1, 1 ] ],
		[ [ Infinity, 1 ], [ 2, 3, 4 ], [ 1, -Infinity ] ],
		[ [ 1, -Infinity ], [ Infinity, 3, 4 ], [ 1, 1 ] ],
		[ [ 1e-300, -1e-300 ], [ 2e-300, 3e-300, 4e-300 ], [ 1e-300, 1e-300 ] ],
		[ [ 1e300, -1e300 ], [ 2e300, 3e300, 4e300 ], [ 1e300, 1e300 ] ]
	];
	var data;
	var a;
	var b;
	var i;
	var j;
	for ( i = 0; i < cases.length; i++ ) {
		data = {
			'N': 3,
			'DL': cases[ i ][ 0 ],
			'D': cases[ i ][ 1 ],
			'DU': cases[ i ][ 2 ]
		};
		a = inputs( data );
		b = inputs( data );
		t.strictEqual( native.apply( null, [ 3 ].concat( a ) ), main.apply( null, [ 3 ].concat( b ) ), 'same status' );
		for ( j = 0; j < 5; j++ ) {
			t.ok( sameBuffer( a[ j ], b[ j ] ), 'same nonfinite/signed-zero buffer' );
		}
	}
	t.end();
});

tape( 'native dispatch preserves original fallback and error behavior', function test( t ) {
	var metadata = [ 'length', 'buffer', 'byteOffset', 'byteLength' ];
	var kernel = factory( function unexpected() {
		t.fail( 'fallback must not call addon' );
	} );
	var views;
	var count;
	var data;
	var a;
	var b;
	var i;
	data = fixtures[ 7 ];
	a = [ data.DL.slice(), data.D.slice(), data.DU.slice(), [ 8 ], [ 8, 8, 8 ] ];
	b = [ data.DL.slice(), data.D.slice(), data.DU.slice(), [ 8 ], [ 8, 8, 8 ] ];
	t.strictEqual( kernel.apply( null, [ 3 ].concat( a ) ), main.apply( null, [ 3 ].concat( b ) ), 'ordinary buffers use fallback' );
	t.deepEqual( a, b, 'ordinary buffer mutations match' );
	t.strictEqual( kernel( 0, null, null, null, null, null ), 0, 'empty call ignores unused buffers' );
	t.throws( function negative() {
		kernel( -1, null, null, null, null, null );
	}, RangeError, 'preserves negative-order error' );
	for ( i = 0; i < metadata.length; i++ ) {
		views = inputs( data );
		count = 0;
		Object.defineProperty( views[ 1 ], metadata[ i ], {
			'get': untrusted
		});
		t.strictEqual( kernel.apply( null, [ 3 ].concat( views ) ), 0, 'own metadata stays on JS' );
		t.strictEqual( count, 0, 'does not invoke ignored metadata getter' );
	}
	views = inputs( data );
	views[ 1 ] = new Float64Array( [ 2 ] );
	t.strictEqual( kernel.apply( null, [ 3 ].concat( views ) ), 0, 'short buffer retains JS behavior' );
	views = inputs( data );
	t.strictEqual( kernel.apply( null, [ '3' ].concat( views ) ), 0, 'coercible order retains JS behavior' );
	t.end();

	function untrusted() {
		count += 1;
		throw new Error( 'unused metadata' );
	}
});

tape( 'pivot/numeric byte aliases retain sequential JavaScript mutations', function test( t ) {
	var kernel;
	var calls = 0;
	var ab = new ArrayBuffer( 80 );
	var bb = new ArrayBuffer( 80 );
	var a = [ new Float64Array( ab, 0, 2 ), new Float64Array( ab, 16, 3 ), new Float64Array( ab, 40, 2 ), new Float64Array( ab, 56, 1 ), new Int32Array( ab, 16, 3 ) ];
	var b = [ new Float64Array( bb, 0, 2 ), new Float64Array( bb, 16, 3 ), new Float64Array( bb, 40, 2 ), new Float64Array( bb, 56, 1 ), new Int32Array( bb, 16, 3 ) ];
	var i;
	kernel = factory( function instrument() {
		calls += 1;
		return addon.apply( null, arguments );
	} );
	a[ 0 ].set( [ 1, 1 ] );
	a[ 1 ].set( [ 2, 3, 1 ] );
	a[ 2 ].set( [ 1, 1 ] );
	b[ 0 ].set( [ 1, 1 ] );
	b[ 1 ].set( [ 2, 3, 1 ] );
	b[ 2 ].set( [ 1, 1 ] );
	t.strictEqual( kernel.apply( null, [ 3 ].concat( a ) ), main.apply( null, [ 3 ].concat( b ) ), 'same alias status' );
	for ( i = 0; i < 5; i++ ) {
		t.ok( sameBuffer( a[ i ], b[ i ] ), 'same cross-type alias view' );
	}
	t.strictEqual( calls, 0, 'overlapping pivot bytes use original JS' );
	t.end();
});

tape( 'the native factors reconstruct the original dense tridiagonal matrix', opts, function test( t ) {
	var expected;
	var matrix;
	var factor;
	var scale;
	var error;
	var temp;
	var data;
	var out;
	var N;
	var i;
	var j;
	var k;
	for ( k = 0; k < fixtures.length; k++ ) {
		data = fixtures[ k ];
		N = data.N;
		out = inputs( data );
		native.apply( null, [ N ].concat( out ) );
		matrix = [];
		for ( i = 0; i < N; i++ ) {
			matrix[ i ] = [];
			for ( j = 0; j < N; j++ ) {
				matrix[ i ][ j ] = ( j === i ) ? out[ 1 ][ i ] : 0.0;
				if ( j === i+1 ) {
					matrix[ i ][ j ] = out[ 2 ][ i ];
				}
				if ( j === i+2 ) {
					matrix[ i ][ j ] = out[ 3 ][ i ];
				}
			}
		}
		for ( i = N-2; i >= 0; i-- ) {
			factor = out[ 0 ][ i ];
			for ( j = 0; j < N; j++ ) {
				matrix[ i+1 ][ j ] += factor*matrix[ i ][ j ];
			}
			if ( out[ 4 ][ i ] === i+1 ) {
				temp = matrix[ i ];
				matrix[ i ] = matrix[ i+1 ];
				matrix[ i+1 ] = temp;
			}
		}
		scale = 0.0;
		error = 0.0;
		for ( i = 0; i < N; i++ ) {
			for ( j = 0; j < N; j++ ) {
				expected = ( j === i ) ? data.D[ i ] : 0.0;
				if ( j === i+1 ) {
					expected = data.DU[ i ];
				}
				if ( j === i-1 ) {
					expected = data.DL[ j ];
				}
				scale = max( scale, abs( expected ) );
				error = max( error, abs( matrix[ i ][ j ]-expected ) );
			}
		}
		t.ok( error === 0.0 || error/scale <= 64.0*2.220446049250313e-16, data.name+': reconstructed matrix residual' );
	}
	t.end();
});
